export function tr(language: Language, value: string): string {
  if (language === 'nl') {
    if (dutchPhrases[value]) return dutchPhrases[value];
    if (value.startsWith('No ')) return `Geen ${tr(language, value.slice(3))}`;
    return value;
  }
  return englishPhrases[value] || value;
}
